unit.decl_stmt:
const lookup = async ({ pid, ppid, user, group, command, all, fields = ['pid', 'ppid', 'comm'] }) => {
	if (! fields.every((field) => validFields.has(field))) {
		throw new Error('ps - invalid field provided');
	}

	if (ppid && fields.indexOf('ppid') < 0) {
		fields.push('ppid');
	}

	const fieldOptions = fields.reduce(reduceFieldsToOptions, [ ]);

	if (pid || pid === 0) {
		const output = await ps([ '-p', processPids(pid), ...fieldOptions ]);

		return parseGrid(output);
	}

	if (ppid || ppid === 0) {
		const pids = processPids(ppid);
		const ppidSet = new Set(String(pids).split(','));
		const output = await ps([ '-p', pids, ...fieldOptions ]);
		const processes = parseGrid(output);

		return processes.filter((proc) => {
			return ppidSet.has(proc.ppid);
		});
	}

	if (all) {
		const output = await ps([ '-e', ...fieldOptions ]);

		return parseGrid(output);
	}

	if (user) {
		const output = await ps([ '-u', user, ...fieldOptions ]);

		return parseGrid(output);
	}

	if (group) {
		const output = await ps([ '-g', group, ...fieldOptions ]);

		return parseGrid(output);
	}

	if (command) {
		const output = await ps([ '-C', command, ...fieldOptions ]);

		return parseGrid(output);
	}

	throw new Error('ps - must provide a search query; one of "pid", "ppid", "all", "user", "group", "command"');
};

unit.class:
class Process {
	constructor(fields) {
		Object.assign(this, fields);
		Object.freeze(this);
	}
}

unit.decl_stmt:
const reduceFieldsToOptions = (options, field) => {
	options.push('-o', field);

	return options;
};

const ps = (args, callback) => {
	return new Promise((resolve, reject) => {
		const child = spawn('ps', args);

		let stdout = '';
		let stderr = '';

		child.on('error', (error) => {
			reject(error);
		});

		child.stdout.on('data', (data) => stdout += data);
		child.stderr.on('data', (data) => stderr += data);

		child.on('close', (code) => {
			stderr = stderr.trim();

			if (stderr) {
				return reject(new Error(stderr));
			}

			resolve(stdout.trim());
		});
	});
};

const isValidPid = (pid) => {
	const int = parseInt(pid, 10);

	return ! isNaN(int) && String(int) === String(pid);
};

decl_stmt.decl:
const processPids = (pid) => {
	if (Array.isArray(pid)) {
		if (! pid.every(isValidPid)) {
			throw new Error('ps - pid must be a valid integer value');
		}

		return pid.join(',');
	}

	if (! isValidPid(pid)) {
		throw new Error('ps - pid must be a valid integer value');
	}

	return pid;
}

unit.decl_stmt:
const parseGrid = (output) => {
	if (! output) {
		return [ ];
	}

	const lines = output.split('\n');
	const header = lines.shift()
		.trim()
		.split(whitespace)
		.map((col) => col.toLowerCase());

	return lines.map((line) => {
		const proc = { };

		line.trim().split(whitespace).forEach((item, index) => {
			if (item) {
				proc[header[index]] = item;
			}
		});

		return new Process(proc);
	});
};

unit.expr_stmt:
module.exports = exports = function(args, callback) {
	if (Array.isArray(args)) {
		args = args.join(' ');
	}
	cp.exec('ps ' + args, function(err, stdout, stderr) {
		stdout = stdout.toString('utf8');
		stderr = stderr.toString('utf8');
		if (err || stderr) {
			return callback(stderr || err);
		}
		callback(null, stdout.trim() || false);
	});
};

exports.lookup = function(query, callback) {
	var format = query.format;

	// Lookup by PID
	if (query.pid) {
		format = parseFormat(format || 'comm pid');

		var pid = Array.isArray(pid)
			? pid.join(',')
			: query.pid;

		return exports([ '-p', pid, '-o', format ], function(err, output) {
			if (err) {
				return callback(err);
			}
			if (query.parse) {
				output = parseGrid(output);
			}
			callback(null, output);
		});
	}

	// Lookup by PPID
	if (query.ppid) {
		format = format || 'comm pid ppid';
		columns = format.split(' ');
		format = parseFormat(format);

		// Parsing is required for ppid queries as we do the filtering internally
		if (query.parse === void(0)) {
			query.parse = true;
		}
		if (! query.parse) {
			throw new Error('ps: the `parse` option cannot be false for ppid queries');
		}

		var ppid = Array.isArray(query.ppid)
			? query.ppid.join(',')
			: query.ppid;

		return exports([ '-p', ppid, '-o', format ], function(err, output) {
			if (err) {
				return callback(err);
			}

			output = parseGrid(output);
			var ppidIndex = columns.indexOf('ppid');

			var ppids = query.ppid;
			if (typeof ppids === 'string') {
				ppids = query.ppid.split(',');
			}
			if (typeof ppids === 'number') {
				ppids = [ ppids ];
			}

			ppids = ppids.map(String);
			output = output.filter(function(line) {
				return (ppids.indexOf(line[ppidIndex]) >= 0);
			});

			callback(null, output);
		});
	}
};

unit.function:
function parseGrid(output) {
	if (! output) {return output;}
	return output.split('\n').map(function(line) {
		var returnedOutput = [ ];
		line.split(/\s+/).forEach(function(item) {
			if (item) {
				returnedOutput.push(item);
			}
		});
		return returnedOutput;
	});
}

function parseFormat(format) {
	if (typeof format === 'string') {
		format = format.split(' ');
	}
	format = format.map(function(item) {
		return item + '=';
	});
	return format.join(' -o ');
}

unit.class:
class tools extends emitter {

  /**
   * @function merge
   * Perform preliminary option/default object merge
   *
   * @param {Object} defaults Application defaults
   * @param {Object} obj User supplied object
   *
   * @returns {Object}
   */
  merge(defaults, obj) {
    return merge(defaults, obj);
  }


  /**
   * @function chunk
   * Defines new property for array's
   * 
   * @param {Array} obj Supplied array
   * @param {Integer} offset Supplied offset
   * 
   * @returns {Array}
   */
  chunk(obj, offset) {
    let idx = 0;
    const alength = obj.length;
    const tarray = [];

    for (idx = 0; idx < alength; idx += offset) {
      tarray.push(obj.slice(idx, idx + offset).join(' '));
    }

    return tarray;
  }


  /**
   * @function flatten
   * Flattens nested arrays into one flat array
   * 
   * @param {Array} arr Array combinator
   * @param {Array} obj User supplied array
   * 
   * @returns {Array}
   */
  flatten(arr, obj) {
    let value;
    const result = [];

    for (let i = 0, length = arr.length; i < length; i++) {

      value = arr[i];

      if (Array.isArray(value)) {
        return this.flatten(value, obj);
      }
      else {
        result.push(value);
      }
    }
    return result;
  }


  /**
   * @function funcs
   * Create functions for use as callbacks
   *
   * @param {Obect} opts Application defaults
   *
   * @returns {Array}
   */
  funcs(opts) {
    const scope = this;
    const funcs = {};
    let cmd = false;
    const errors = [];
    const reports = [];

    if (opts.range.length <= 0)
      return "Range of hosts could not be created";

    Object.keys(opts.range).forEach(function blocks(block) {

      // Acquire an array of ranges
      const range = opts.range[block];

      // Create a new function for each range block
      funcs[range] = function block(callback) {
        const report = [];


        // Capture the flags, & ranges as a command string
        cmd = scope.command(opts, range);

        // Split up cmd for .spawn()
        const obj = cmd.split(" ");
        cmd = obj[0];
        const args = obj.slice(1);

        if (opts.verbose)
          console.log(`Running: ${cmd}`);

        // Push it on to the heap
        const execute = proc(cmd, args);

        // Discard stderr for now, maybe log?
        execute.stderr.on('data', (chunk) => {
          /* Silently discard stderr messages to not interupt scans */
        });

        // Push to array of reports
        execute.stdout.on('data', (chunk) => {
          report.push(chunk);
        });

        // Push report array to reporting function on stream end
        execute.stdout.on('end', () => {
          if (report.length > 0)
            return reporting.reports(opts, report, callback);
        });
      };
    });

    return funcs;
  }


  /**
   * @function command
   * Generate nmap command string
   *
   * @param {Object} opts - User supplied options
   * @param {String} block - Network block
   *
   * @returns {String} NMAP scan string
   */
  command(opts, block) {
    const flags = opts.flags.join(' ');
    const proto = (opts.udp) ? ' -sU' : ' ';
    const to = `--host-timeout=${opts.timeout}s `;
    const ipv6 = (validation.test(validation.patterns.IPv6, block)) ?
      ' -6 ' : ' ';

    return (opts.ports) ?
      `${opts.nmap+proto} ${to}${flags}${ipv6}-p${opts.ports} ${block}` :
      `${opts.nmap+proto} ${to}${flags}${ipv6}${block}`;
  }


  /**
   * @function worker
   * Executes object of functions
   *
   * @param {Object} obj User supplied object
   * @param {Function} fn Return function
   */
  worker(obj, fn) {
    async.parallelLimit(obj.funcs, obj.threshold, fn);
  }


  /**
   * @function init
   * @scope private
   * Merges supplied options & builds functions
   *
   * @param {Object} defaults libnmap default options
   * @param {Object} opts User supplied configuration object
   * @param {Function} cb Callback
   *
   * @returns {Object}
   */
  init(defaults, opts, cb) {
    let funcs = [];
    const ranges = [];
    const called = caller.get()[1].getFunctionName();

    /* Override 'defaults.flags' array with 'opts.flags' (prevents merge) */
    if (/array/.test(typeof opts.flags))
      defaults.flags = opts.flags;

    opts = this.merge(defaults, opts);

    /* Ensure we can always parse the report */
    if (opts.flags.indexOf('-oX -') === -1)
      opts.flags.push('-oX -');

    /* If we are in a discover mode get adapters for associated network(s) */
    if (/nmap.discover/.test(called)) {

      /* Bail early if we cannot determine any ranges */
      if (!(opts.range = network.adapters(opts)))
        return cb(validation.messages.version);

      /* Set scan options as static values for 'discover' mode */
      opts.ports = '';
      opts.flags = [
        '-n',
        '-oX -',
        '-sn',
        '-PR'
      ];
    }

    validation.init(opts, (err, result) => {
      if (err)
        return cb(err);

      opts.range = network.calculate(opts);
      funcs = this.funcs(opts);

      return cb(null, {
        opts,
        funcs
      });
    });
  }
}

