				case 'workspace':
					console.log(`Uploading to ${opts.appID} - Workspace Files...`);
					break;
				case 'plugin':
					console.log(`Uploading to ${opts.appID} - ${opts.pluginName} - Plugin Files...`);
					break;
				default:
					console.log(`Uploading to ${opts.appID} - Application Static Files...`);
			}

